#!/usr/bin/env python3
"""Writes stdlib/abla/ct/entry.ab. Run it after changing the surface and commit its output."""
import pathlib

out = []
w = out.append
w('''// Constant-time primitives: secret integers no `if`, index or comparison takes, and masks and
// selects the optimizer can't turn into a branch (docs/constant-time.md, docs/stdlib/ct.md).
// Generated by tools/ct/gen-stdlib.py; change that and run it again.

import "abla/unsafe/memory/raw"

noescape extern:"intrinsic" fun ablaCtNarrowTarget(): bool

@inline fun ctJoin(low: u32, high: u32): secretU64 = ablaCtSecret_u64((u64(high) << 32) | u64(low))

@inline fun ctAddHalves(aLow: u32, aHigh: u32, bLow: u32, bHigh: u32): secretU64 {
    val low = aLow + bLow
    val carry = ((aLow & bLow) | ((aLow | bLow) & ~low)) >> 31
    ctJoin(low, aHigh + bHigh + carry)
}

@inline fun ctSubHalves(aLow: u32, aHigh: u32, bLow: u32, bHigh: u32): secretU64 {
    val low = aLow - bLow
    val borrow = ((~aLow & bLow) | ((~aLow | bLow) & low)) >> 31
    ctJoin(low, aHigh - bHigh - borrow)
}

// All ones in a word if the first number is less than the second, else zero.
@inline fun ctBorrowHalves(aLow: u32, aHigh: u32, bLow: u32, bHigh: u32): u32 {
    val low = aLow - bLow
    val borrow = ((~aLow & bLow) | ((~aLow | bLow) & low)) >> 31
    val high = aHigh - bHigh - borrow
    u32(0) - (((~aHigh & bHigh) | ((~aHigh | bHigh) & high)) >> 31)
}
''')
for bits in [8, 16, 32, 64]:
    u = f"u{bits}"
    s = f"secretU{bits}"
    top = bits - 1
    plus_minus = f"""@inline operator fun {s}.plus(other: {s}): {s} = ablaCtSecret_{u}(ablaCtBits_{u}(this) + ablaCtBits_{u}(other))
@inline operator fun {s}.minus(other: {s}): {s} = ablaCtSecret_{u}(ablaCtBits_{u}(this) - ablaCtBits_{u}(other))"""
    # Not the usual (x | -x) >> top: LLVM and wasm-opt both know that one for a compare, and the
    # module wasm-opt then writes has a select on the secret, which an engine may branch on.
    nonzero = f"""    val bits = ablaCtBits_{u}(value)
    val rest = ~({u}(1) << {top})
    ablaCtSecret_{u}({u}(0) - ((((bits & rest) + rest) | bits) >> {top}))"""
    lt = f"""    val x = ablaCtBits_{u}(a)
    val y = ablaCtBits_{u}(b)
    val borrow = ((~x & y) | ((~x | y) & (x - y))) >> {top}
    ablaCtSecret_{u}({u}(0) - borrow)"""
    if bits == 64:
        # On a 32-bit target LLVM makes 64-bit carries and compares out of branches, as
        # tools/test-ct.sh saw on Xtensa, so there they are done in halves, in plain arithmetic.
        plus_minus = """@inline operator fun secretU64.plus(other: secretU64): secretU64 {
    val a = ablaCtBits_u64(this)
    val b = ablaCtBits_u64(other)
    if (ablaCtNarrowTarget()) ctAddHalves(u32(a), u32(a >> 32), u32(b), u32(b >> 32))
    else ablaCtSecret_u64(a + b)
}
@inline operator fun secretU64.minus(other: secretU64): secretU64 {
    val a = ablaCtBits_u64(this)
    val b = ablaCtBits_u64(other)
    if (ablaCtNarrowTarget()) ctSubHalves(u32(a), u32(a >> 32), u32(b), u32(b >> 32))
    else ablaCtSecret_u64(a - b)
}"""
        nonzero = f"""    val bits = ablaCtBits_{u}(value)
    if (ablaCtNarrowTarget()) {{
        val word = ablaCtBits_u32(ctIsNonZero(ablaCtSecret_u32(u32(bits) | u32(bits >> 32))))
        return ablaCtSecret_u64((u64(word) << 32) | u64(word))
    }}
    val rest = ~({u}(1) << {top})
    ablaCtSecret_{u}({u}(0) - ((((bits & rest) + rest) | bits) >> {top}))"""
        lt = """    val x = ablaCtBits_u64(a)
    val y = ablaCtBits_u64(b)
    if (ablaCtNarrowTarget()) {
        val word = ctBorrowHalves(u32(x), u32(x >> 32), u32(y), u32(y >> 32))
        return ablaCtSecret_u64((u64(word) << 32) | u64(word))
    }
    val borrow = ((~x & y) | ((~x | y) & (x - y))) >> 63
    ablaCtSecret_u64(u64(0) - borrow)"""
    w(f'''noescape extern:"intrinsic" fun ablaCtSecret_{u}(value: {u}): {s}
noescape extern:"intrinsic" fun ablaCtBits_{u}(value: {s}): {u}

/** `value` as a secret: the compiler no longer knows anything about it. */
@inline fun {s}(value: {u}): {s} = ablaCtSecret_{u}(value)

/** The bits, as a public value. Branch on them or index with them only if they may be known. */
@inline fun {s}.declassify(): {u} = ablaCtBits_{u}(this)

{plus_minus}
@inline operator fun {s}.times(other: {s}): {s} = ablaCtSecret_{u}(ablaCtBits_{u}(this) * ablaCtBits_{u}(other))
@inline operator fun {s}.and(other: {s}): {s} = ablaCtSecret_{u}(ablaCtBits_{u}(this) & ablaCtBits_{u}(other))
@inline operator fun {s}.or(other: {s}): {s} = ablaCtSecret_{u}(ablaCtBits_{u}(this) | ablaCtBits_{u}(other))
@inline operator fun {s}.xor(other: {s}): {s} = ablaCtSecret_{u}(ablaCtBits_{u}(this) ^ ablaCtBits_{u}(other))
@inline operator fun {s}.inv(): {s} = ablaCtSecret_{u}(~ablaCtBits_{u}(this))
/** A public count: the amount shifted isn't hidden. */
@inline operator fun {s}.shl(count: int): {s} = ablaCtSecret_{u}(ablaCtBits_{u}(this) << count)
@inline operator fun {s}.shr(count: int): {s} = ablaCtSecret_{u}(ablaCtBits_{u}(this) >> count)
@inline fun {s}.rotl(count: int): {s} {{
    val n = count & {top}
    if (n == 0) this else ablaCtSecret_{u}((ablaCtBits_{u}(this) << n) | (ablaCtBits_{u}(this) >> ({bits} - n)))
}}
@inline fun {s}.rotr(count: int): {s} = this.rotl({bits} - (count & {top}))

/** All ones if `value` isn't zero, else zero. */
@inline fun ctIsNonZero(value: {s}): {s} {{
{nonzero}
}}

/** All ones if `value` is zero, else zero. */
@inline fun ctIsZero(value: {s}): {s} = ~ctIsNonZero(value)

/** All ones if they are equal, else zero. */
@inline fun ctEq(a: {s}, b: {s}): {s} = ctIsZero(a ^ b)

/** All ones if `a` is less than `b`, as unsigned, else zero. */
@inline fun ctLt(a: {s}, b: {s}): {s} {{
{lt}
}}

/** All ones if bit 0 of `value` is set, else zero. */
@inline fun ctFromLowBit(value: {s}): {s} = ablaCtSecret_{u}({u}(0) - (ablaCtBits_{u}(value) & {u}(1)))

/** `a` where `mask` has ones, `b` where it has zeros. The mask goes through the barrier
 *  again: this is the one pattern LLVM most wants to make a select. */
@inline fun ctSelect(mask: {s}, a: {s}, b: {s}): {s} {{
    val mask2 = ablaCtBits_{u}(ablaCtSecret_{u}(ablaCtBits_{u}(mask)))
    ablaCtSecret_{u}((mask2 & ablaCtBits_{u}(a)) | (~mask2 & ablaCtBits_{u}(b)))
}}
''')
w('''@inline fun secretU32.widen(): secretU64 = ablaCtSecret_u64(u64(ablaCtBits_u32(this)))
@inline fun secretU64.low(): secretU32 = ablaCtSecret_u32(u32(ablaCtBits_u64(this)))
@inline fun secretU64.high(): secretU32 = ablaCtSecret_u32(u32(ablaCtBits_u64(this) >> 32))
@inline fun secretU8.widen(): secretU32 = ablaCtSecret_u32(u32(ablaCtBits_u8(this)))
@inline fun secretU32.lowU8(): secretU8 = ablaCtSecret_u8(u8(ablaCtBits_u32(this)))

/** All ones if `count` bytes at each address differ anywhere, else zero: every byte is read
 *  whatever the others are. What the addresses and `count` are isn't hidden. */
@inline trusted fun ctDifferenceAddress(left: int, right: int, count: int): secretU8 {
    var difference = ablaCtSecret_u8(u8(0))
    for (at in 0 until count) {
        val a = ablaUnsafeLoadU8(ablaUnsafePointerOffset(ablaUnsafeNullPointer(), left + at))
        val b = ablaUnsafeLoadU8(ablaUnsafePointerOffset(ablaUnsafeNullPointer(), right + at))
        difference = difference | (ablaCtSecret_u8(u8(a)) ^ ablaCtSecret_u8(u8(b)))
    }
    ctIsNonZero(difference)
}

/** Whether two strings are equal, reading every byte. Their lengths aren't secret: different
 *  ones are unequal at once. */
trusted fun ctEquals(left: string, right: string): bool {
    if (left.size != right.size) return false
    ctDifferenceAddress(
        ablaUnsafeStringAddress(left), ablaUnsafeStringAddress(right), left.size
    ).declassify() == u8(0)
}
''')
path = pathlib.Path(__file__).resolve().parents[2] / "stdlib/abla/ct/entry.ab"
path.write_text("\n".join(out))
